template <class LockType>
class __attribute__((scoped_lockable)) BasicAutoLock {
 public:
  struct AlreadyAcquired {};

  explicit BasicAutoLock(LockType& lock) __attribute__((exclusive_lock_function(lock)))
      : lock_(lock) {
    lock_.Acquire();
  }

  BasicAutoLock(LockType& lock, const AlreadyAcquired&)
      __attribute__((exclusive_locks_required(lock)))
      : lock_(lock) {
    lock_.AssertAcquired();
  }

  BasicAutoLock(const BasicAutoLock&) = delete;
  BasicAutoLock& operator=(const BasicAutoLock&) = delete;

  ~BasicAutoLock() __attribute__((unlock_function())) {
    lock_.AssertAcquired();
    lock_.Release();
  }

 private:
  LockType& lock_;
};


template <class LockType>
class __attribute__((scoped_lockable)) BasicAutoTryLock {
 public:
  explicit BasicAutoTryLock(LockType& lock) __attribute__((exclusive_lock_function(lock)))
      : lock_(lock), is_acquired_(lock_.Try()) {}

  BasicAutoTryLock(const BasicAutoTryLock&) = delete;
  BasicAutoTryLock& operator=(const BasicAutoTryLock&) = delete;

  ~BasicAutoTryLock() __attribute__((unlock_function())) {
    if (is_acquired_) {
      lock_.AssertAcquired();
      lock_.Release();
    }
  }

  bool is_acquired() const { return is_acquired_; }

 private:
  LockType& lock_;
  const bool is_acquired_;
};


template <class LockType>
class BasicAutoUnlock {
 public:
  explicit BasicAutoUnlock(LockType& lock) : lock_(lock) {

    lock_.AssertAcquired();
    lock_.Release();
  }

  BasicAutoUnlock(const BasicAutoUnlock&) = delete;
  BasicAutoUnlock& operator=(const BasicAutoUnlock&) = delete;

  ~BasicAutoUnlock() { lock_.Acquire(); }

 private:
  LockType& lock_;
};


template <class LockType>
class __attribute__((scoped_lockable)) BasicAutoLockMaybe {
 public:
  explicit BasicAutoLockMaybe(LockType* lock) __attribute__((exclusive_lock_function(lock)))
      : lock_(lock) {
    if (lock_)
      lock_->Acquire();
  }

  BasicAutoLockMaybe(const BasicAutoLockMaybe&) = delete;
  BasicAutoLockMaybe& operator=(const BasicAutoLockMaybe&) = delete;

  ~BasicAutoLockMaybe() __attribute__((unlock_function())) {
    if (lock_) {
      lock_->AssertAcquired();
      lock_->Release();
    }
  }

 private:
  LockType* const lock_;
};



template <class LockType>
class __attribute__((scoped_lockable)) BasicReleasableAutoLock {
 public:
  explicit BasicReleasableAutoLock(LockType* lock) __attribute__((exclusive_lock_function(lock)))
      : lock_(lock) {
    true ? (void)0 : ::logging::VoidifyStream(!(lock_)) & (*::logging::g_swallow_stream);
    lock_->Acquire();
  }

  BasicReleasableAutoLock(const BasicReleasableAutoLock&) = delete;
  BasicReleasableAutoLock& operator=(const BasicReleasableAutoLock&) = delete;

  ~BasicReleasableAutoLock() __attribute__((unlock_function())) {
    if (lock_) {
      lock_->AssertAcquired();
      lock_->Release();
    }
  }

  void Release() __attribute__((unlock_function())) {
    true ? (void)0 : ::logging::VoidifyStream(!(lock_)) & (*::logging::g_swallow_stream);
    lock_->AssertAcquired();
    lock_->Release();
    lock_ = nullptr;
  }

 private:
  LockType* lock_;
};

